) AS (
  VALUES 
    (507::BIGINT, 'Quices duros todas las semanas porque solo su curso importa, con tiempo apenas para uno de los dos ejercicios. Dura dos horas o más y casi no se avanza, pero para hablar de sus años en la u sí hay tiempo. Odioso y prepotente, si alguien habla golpea el escritorio. Demasiado molesto.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-19T00:00:00+00:00'::TIMESTAMPTZ, 'ef4dce8cffaca029cf4c25759464e249720fea1ad8ec33553ee1e2f90dbccb0e'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Si son buenos siendo autodidactas matriculen con este profe, sino no. Él explica solo una vez los temas y después de ahí uno es el encargado de hacer ejercicios y estudiar por su cuenta. En clases da muy pocos ejemplos y la mayoría son super sencillos. Hace quices complicados todas las semanas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos exámenes']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '5090f75044d2701a92f1c8c5e619ab16c83957562990f8497710e046d1d0ee86'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'El curso puede ser pesado, él no ayuda mucho pues sus explicaciones aunque muy buenas, son simples. Personaje raro pasivo-agresivo, da miedo. Él tiene a su asistente de confianza un chavalo, si ese semestre le toca a otro diferente puede que se haga todavía más complicado pues el primero es chill'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'c3731b0147136ca957cca88e27e769c1e6916bd8925ee4b4a671b6c546fbea0c'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Es un profesor terrible, no matricule con él, en la escuela hay profes mucho mejores, tiene problemas mentales, habla solo de la vida de él y no da ejemplos buenos solo los más fáciles, parece que no sabe realmente los temas y en los parciales viene materia que nunca se vio con él, toca ser 100%Au D'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '93c31775b9d5e14e7f07d41166eb385e4d0ea48cc751edead366a55bc96c2df7'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Sus quices semanales ayudan a mantener la materia al día, a los estudiantes que asistieron a la mayoría de las clases les ayudo con la nota de un quiz, sin embargo puede tener actitudes curiosas aveces. Explica bien y no califica tan duro'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'a7598de8bb6773cdd93d5ac6c2820babbe428d3876bda729990f47827dafc7ae'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Viejo amargado y repugnante. Las clases las da siper simples en comparacion de ejercicios reales de examen. Hace quiz todas las primeras clases de la semana, lo unico bueno es que hace la clase presencial y virtual a la vez, y queda todo grabado. Viejo s0plav3rgas'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '5196407432cc88fbf661c7c6720c733e5eb91688ceeaf0131bdf3394f5296965'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-01T00:00:00+00:00'::TIMESTAMPTZ, '28c483b71a1e6d27b0136cfa750a6f2a1d36eeb17037039ba77785ccf2cb536d'::TEXT, ARRAY[605]::BIGINT[]),
    (507::BIGINT, 'Se nota que le gusta dar la clase, pero en el momento que una persona le pregunte algo se toma varios minutos tratándolo a veces de tonto o de que ya explicó eso (a veces sí ya lo había explicado, pero él se lo toma como una ofensa prácticamente). Deja las clases grabadas y PDF. A vecehastapeleasolo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'bf5f02f63640b8ec31ddc141bfd9bd9089e306b60320158b1e114e0a6d4d287a'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'lo matricule porque en este sitio salia que era muy bueno y la verdad que esta como 6/10, es muy lenta la clase y si alguien pregunta algo puede durar buen rato jodiendo al que pregunto mas que responder la pregunta y si cansa demasiado la clase. y la verdad que esa calificacion del sitio no cumple'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'ab1e880906cfaf782d19cf1380a1367815257bc2f32eb8b91144892b6ecf487b'::TEXT, ARRAY[605]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '0eb10c6d668e47b6749e8a73d17b3d32e509f8928a79ecee51d92b4a4c940e06'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'La verdad no, de los peores profesores que he tenido, deja las cosas grabadas pero por el resto es re malo, se burla de la gente que no entiende, o si uno no sabe como hace algo que el “ya explico”, los quices siento que son difíciles porque muchas de las veces son cosas más difíciles o no vistas'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '661c7a50f9fd6d3bca2f8a968c46a6a68f496997199f58991dfe1c5df9b23bb3'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Graba las clases que es una ventaja muy buena, hace quices todas las semanas, no son muy dificiles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos exámenes', 'Aspectos de calificación claros']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'e0f9e43dd5e7510a0120789fbcbc7a5d7866c0fc9dd51ef0db2baafd050b4cc5'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Le gusta mucho dar las clases y explica muy bien, deja los pdfs de la clase y grabaciones subidas para repasar, hace quiz semanal y eso hace que uno pase repasando, excelente profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '738c2a3fc590aa0ec51a1d2ea46c9a223da0e846dbd3e7934f72a6646b0d35e6'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'EL PEOR PROFESOR DEL MUNDO. Les recomiendo full NO matricular con él. Suele burlarse si algún estudiante pregunta algo (que puede ser obvio) pero aún así no es lógico. Las quices fáciles, si, pero fuera de eso todo mal. No sabe explicar'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b7608696dd5ef71fcaf481d0b345dfffab97a7348433ee95ccd10510c7d0a744'::TEXT, ARRAY[605]::BIGINT[]),
    (507::BIGINT, 'Lo único bueno que tiene es que graba las clases, solo explica teoría y hace un par de ejemplos, usted tiene que ser bastante más autodidacta que con el resto, él asume que usted la mayoría lo sabe y que usted solo lleva un curso'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'ed82fc24770ad9992136a9cc95b6ee4d208218afc8f09ddb910af21148c1bb83'::TEXT, ARRAY[1018]::BIGINT[]),
    (507::BIGINT, 'No lo recomiendo, sal uno tardísino en pleno verano de clases que son los mismos ejemplos de siempre. No pierda tiempo'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos exámenes']::TEXT[], '2024-10-04T00:00:00+00:00'::TIMESTAMPTZ, '10938cfc11fb76171ce93ab09756e359cb64ea800e58e138c3f3c60e197c7ec9'::TEXT, ARRAY[1018]::BIGINT[]),
    (507::BIGINT, 'Tipazo, explica muy bien, deja las clases grabadas por si ocupas revisar algo y estará dispuesto a solventar dudas. La única pega es que sí califica durillo'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3d77ca47428c59a3a4c2cdd3a03bb7f715f12ba794e4085068f4342723c27e24'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Ni tan malo ni tan bueno, no obstante, deben tener la material al día, sería mejor si la tienen adelantada. Hace pruebas cortas todas las semanas, normalmente de ejercicios sacados de cátedra, explica muy poco, se disgusta cuando los estudiantes preguntan algo obvio.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c5c57f7f19cbfaef61fa08d2c8a33d24761ff1dbc9757fc0ca1724a97fd298cc'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'adf173a2a08dc31e9131daf4854510c04c057c99d96797b656d23762e8d39e35'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Si tienen la posibilidad de matricular con él, evitenla, no van aprender nada, asume que ya todo lo sabemos, da pocos ejemplos y es egocentrico, quita las ganas de seguir yendo a la clase.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'e3f2805ee0f7be6af21acc607239921f9a798c6fa83dd5365885deef494a42a9'::TEXT, ARRAY[2439]::BIGINT[]),
    (507::BIGINT, 'Si pueden evitar matricular con el haganlo. Explica terrible, hace solo un ejemplo y aveces ni lo termina. Ve todo por encima. Hace quizes semanales pero no son muy faciles tampoco.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '4672b21630c20f9c99f24c5948b2d95045323f67f246c71ed452d05493b295cd'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'No lo recomiendo para nada ya que el profesor asume que uno sabe y si pregunta se enoja, muy egocentrico , no lo recomiendo, eviten llevar un curso con el'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-02-21T00:00:00+00:00'::TIMESTAMPTZ, 'cfd7459b6fb2f95f76a0a2734cc0b8e1f79da1cf2735736b282dcfcfe696bbf0'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (507::BIGINT, 'Suele llegar a resolver ejercicios de catedra, tiene un humor pesado, y suele asumir que ya sabemos todo, cuando pide que le respondan algo, asegúrese de responder bien porque sino va a decir algo de mal gusto para dejarte mal. Además, hace un quiz todas las semanas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '8da9673fe215ac8a373b1fe59418cf38aaa3b7b2c39418e5563ccb134ff05a81'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Típico profesor basura en el TEC, si llevan ED con el, háganlo solo si ya han llevado el curso antes, guíense con videos de Youtube de otros profes, con el no van a aprender nada, pasa sus clases regañando, haciendo comentarios innecesarios, hablando basura'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '6c723e889b4b43de09d74938ecd74c7ed4c70f57e1a73030e2921545cefd00ab'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'El profe tiene cosas buenas, como siempre hace reuniones de teams y graba la clase presencial y hace quices todas las semanas, pero hay que ser autodidacta para poder sacar buenas notas, el profe no explica nada. No lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-09-13T00:00:00+00:00'::TIMESTAMPTZ, 'bcded64208809223bf936e9a4108eb2e81c0d12d63eb9548f66b6cd0cea1e980'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'El profe explica bien, sin embargo, si van a matricular con él tienen que dedicar mucho tiempo fuera de clase para practicar, en clase resuelve pocos ejercicios. Las clases eran cortas, lo bueno es que siempre hacia una reunión en teams por si a alguien se le complicaba asistir presencialmente.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0a589e9b37b2f89ea3315962f657b3b94131a2752521d46f65c5a340c5cceeab'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Muy mal profe, no sabe explicar y es muy confuso a la hora de las clases, si matriculan con el, dediquen mucho tiempo a ver clases aparte, porque con las explicaciones de el, no son suficientes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b44fa82ead56ba1e4045539789128bb256b0c7ebf9ddf058952be45059bf33ef'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'desordenado, a pesar de que hacen un plan de clase viendo el programa del curso, da la mitad de la materia si la tiene que llevar con el estudie usted solo con ese mismo plan, , se enoja si la clase no sabe algo porque es super básico, habla públicamente a los estudiantes si hacen algo mal en exams'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '2c64bf3d412d5e1d8f19d4a629d7d637c8b292858ee4531c30654baec14591f7'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'El curso sería fácil si el se empeñara en explicar bien. El curso lo pase con base de videos de youtube y practicas externas. No me gustaría volver a llevar algo con este profe.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ceec570c5277728ee5127c65785425334e5c23c7b7c475897d4cec17b57853ad'::TEXT, ARRAY[2444]::BIGINT[]),
    (507::BIGINT, 'El profesor cree que uno ya sabe todo, explica muy rápido y se enoja si alguien pregunta. Los exámenes son muy difíciles ya que, tiene algunas cosas que no se explicaron.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '23b58a0e40b5835aa445a9c674bb711b461865f9e7d1d0c97fb273f7c77aaa1b'::TEXT, ARRAY[2444]::BIGINT[]),
    (507::BIGINT, 'Explica muy bien y siempre está pendiente de que podamos tener las notas publicados. Como profesor excelente, aunque es un poco egocéntrico, lo que en realidad no afecta en nada el curso. Lo llevé en modalidad virtual'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'f5daaca8d935ccb181afc589acedbc99df6e3b6aeac829538be5cb47d4c90fde'::TEXT, ARRAY[2444]::BIGINT[]),
    (507::BIGINT, 'Se pone muy nervioso si los estudiantes no participan. Las clases se hacían eternas y deja muchas tareas. Si uno tenía una duda en alguna de las tareas o exámenes solo las aclaraba en la hora de consulta. Él sube a la plataforma el libro y un PDF con lo que hicimos en la clase de cada semana.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '27718523c6179aa125e71b7d5e9f0d49c3372f32e140c1c54abafee9699af73c'::TEXT, ARRAY[2444]::BIGINT[]),
    (507::BIGINT, 'Si da muy bien la materia pero explica con pocos ejemplos y además se hace la víctima cada rato solo porque los estudiantes no participan en clases, como quiere que participe si a veces no se entiende un carajo! En presencial cada rato se paraba hablar paja ???? ya ahora virtual no habló mucho.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'c30708d91eefe307cefb1f90fbb110315d77b3255732fc06afb1b04939c79e21'::TEXT, ARRAY[2444]::BIGINT[]),
    (507::BIGINT, 'Es un profesor que parece tener un ego enorme. Es muy indiferente al tratar al estudiante. Además, él cree que el estudiante es un erudito en matemáticas, por tanto, no explica mucho ya que piensa que ciertos temas se ven en el colegio, no siendo el caso. Muy arrogante. Sus clases son "obligatorias"'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'c53fad40c4175b9c7bc614d8568a7aa306640d0c5e104bc2c1980e0b37488983'::TEXT, ARRAY[2444]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2020-02-17T00:00:00+00:00'::TIMESTAMPTZ, '7fc7fa61b125e63196b5a4c7354abd795d8f9b097e4a0ea0001c02de71a1e2b7'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3787ede851e10229c2eb0fb1b4339af8eae7b0b4ebe1864d3fbe63e31ae4a355'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Sabe explicar pero se interrumpe cada 5 minutos para hablar paja o para cagar a alguien que no está viendo la pizarra /usando el celular. Pasa golpeando la pizarra para que ud deje de copiar y vea lo que él está haciendo para alimentarle el ego. Es muy molesto y prepotente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-16T00:00:00+00:00'::TIMESTAMPTZ, '3fa6e93e265b0641dfb8bfc33e4fb9bb8a05ff7af0dccac8bc012c4ea2e11d0f'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'No use el celular y todo irá de maravilla, si tiene sus salidas de "cae mal", pero las dudas que tenga, él se las resuelve. Deja mucha tarea moral e insta a que vayan a hora de consulta, además que no califica tan duro los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-12-05T00:00:00+00:00'::TIMESTAMPTZ, '0c4f8d85855103afc9416a76feb56e04824e115dc427c1e35b5e47e02e217418'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'En general buen profe, muy antipático y todo pero en lo que importa que es la materia del curso la brinda super clara.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'f8b0eb1f8d66168a447e256b9f21d8a56ff0138a08e69bc5772aa9a8da8fbdc7'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'El profe es pésimo se enoja x nada se tira flores de que es buenísimo y no lo es nos manda muy mal para el examen por cada temas explica como 3 ejercicios es pésimo, no lleve algo con él y le encanta hablar de todo y de nada, essuper aburrido y no quiere q alguien falte y que salga mal en los quices'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, '03d8684781e1d581c485ef2e2d219c85e5c5cc3bad6b7156639e7562137dae20'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Muy aburrido, como dicen los comentarios pasivo agresivo. Hace quices semanales, se enoja si uno sale mal. Mal trato al estudiante. Manda indirectas a estudiantes sobre lo quer uno falla en un quiz. Si falta a clase, se lo hecha en la cara. Lleve el curso semivirtual, no pierda el tiempo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchos exámenes']::TEXT[], '2019-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'a86d271a44cb9907c997e116caa5b9aa9f229d883bd50c0ac9275731f0fa404a'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'aburrido y medio. No le cuadra que uno falte jajaj y el mae está medio camote'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-21T00:00:00+00:00'::TIMESTAMPTZ, '7a4655217fd54b08375523a0361dfaf1257e0c4a423ef63d8058a183b4330f04'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Estoy a un semestre de graduarme y luego de haber cursado casi una carrera entera puedo decir con seguridad que es el profe más grosero, pedante, arrogante que he tenido en mi vida. De pase explica bastante claro pero no vale la pena el trato.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-08-31T00:00:00+00:00'::TIMESTAMPTZ, '585ba4c07bc09c5346f0b44cb405b3f1128370a4437a0e6a9616fe6f232f51d9'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Super mal profesor, pasivo agresivo asume que los estudiantes saben todo en fin no te prepara bien para los exámenes'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b0c3604b44b1e5b4dc3a173300fbb996780d791be80a87565853c68be56d390c'::TEXT, ARRAY[1018]::BIGINT[]),
    (507::BIGINT, 'Es muy pasivo-agresivo. Por tema se hacen como 3 ejercicios. El examen de reposición lo hace para no pasarlo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3bea7bc7223a84cd1f9da0717719cbbcc13a6e2b1edd9bcbf839806c4548a325'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (507::BIGINT, 'No volvería a tomar una clase con él, da pocos ejemplos y la forma de explicarlos es un poco peculiar, parece que asume que los estudiantes ya saben lo que está haciendo. Pasé el curso pero necesité material de apoyo de otros profesores porque no explicaba ejercicios de compleja resolución.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c03ce3425c0874e5c26e0f922672812af08bd651451d5ff140f6f64cdad72d55'::TEXT, ARRAY[1018]::BIGINT[]),
    (507::BIGINT, 'Hace quices semanales de la materia que deja en las tareas morales y lo que se vio la clase pasada. Los quices son más fuertes que los exámenes y eso ayuda mucho. No deja tareas reales ni materia para leer fuera de clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6efe2b7c9b7381d1fa4947bc36f5f1b8027847559b64e387b8fe11d088bb31a4'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Hace quices semanales de materia que ya se vió. No son sorpresa y generalmente tienen que ver con la tarea moral que deja. Explica muy claro, todo lo escribe en la pizarra. Explica y atiende dudas cuantas veces sea necesario. Reconoce a los que más participan, pero no desprecia a los que no lo hacen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '06b9f62a2546d3b2ecfbd875bbf374947d2d30cc4d856d9270e46f723bee7aca'::TEXT, ARRAY[1018]::BIGINT[]),
    (507::BIGINT, 'Muy buen profesor, explica muy claro y respeta a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '9e090ea2270109b39a8a6fdd94351cf93c3c5d4264196b2f406d1083b1d7b7f4'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Meta sin miedo con el Chiqui'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'd4ed4bfc36f22cce92cc433e25a56d43576cd63e3fac911c2737b417b68052bc'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Hace que el curso sea aún más fácil, es muy dedicado a su trabajo y disciplinado. El detalle que tiene es que va demasiado despacio, se detiene a regañar a los irresponsables y golpea la pizarra para que uno ponga atención, llega a parecer de colegio.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-04T00:00:00+00:00'::TIMESTAMPTZ, '6efb0b7994c61e14af775b646e4c1da028eca616874dcedfafbac4195a926398'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Hace quices todas las semanas y eso ayuda mucho. Explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '6fd1a9a679f4b9639d33f87af181995d9f2c9311764a46dc602ed33771abd2b2'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '9be3ac57cd4b246a430f38cb02e7147ef0e7aa04a8a896d76033d00a57fb5ad7'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Es muy buen profe. Es increíblemente ordenado y muy claro al explicar. Le encanta la puntualidad y deja afuera a la gente si llega tarde, pero en sus clases se aprende de verdad.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '3c7b236e7b74a82115ba642c07480b7bc114e2ffc80ded7b6ca3945538b72b65'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Excelente explicando, da muchos ejemplos en clase y hace quices todas las semanas. Algunas veces es un poco repugnante pero lo compensa con la claridad de la materia. Se preocupa por que el estudiante aprenda.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'af0ade42a92164f3c7b6fa3f5d028583b58985a82170c844acc119d39a5a6641'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Excelente profesor, es muy ordenado y te da tiempo para resolver los problemas por tu cuenta en la clase. Le encanta la puntualidad y cuenta historias muy constructivas. Califica lo justo. El único problema es que es un poco engreído y no ayuda mucho en consulta. Quices todas las semanas.Recomendado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c25f55c4250aa3c32548355f4b9ccad503214b6357c918933194f268e2c9fe68'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Buen profesor, es ordenado, explica bien, deja quices todas las semanas como método para que el estudiante no descuide el curso, pide el mismo orden que es otorga.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2017-07-01T00:00:00+00:00'::TIMESTAMPTZ, '25db70c62a0830397424465d7d8b49730b58a4d4d5a78283cc88c3d9493e08c7'::TEXT, ARRAY[605]::BIGINT[]),
    (507::BIGINT, 'En clases es muy ordenado y explica muy bien. Lo malo es que hace quices todas las semanas. En los examenes califica justo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, '0133b0958cfc3829b61a6f1dfcb67220b12bf367114badb815be9cc9bcc51dd8'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Explicando es demasiado bueno, ademas es muy ordenado a la hora de dar la clase, escribe muy ordenado, para tomar apuntes. con el tendrás lo necesario para salir bien en el examen. Los quices son bastante difíciles. Si buscas de su ayuda, siempre te atenderá.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, '9a59882d1ae634ebeae1310cd6a002c6dacf03038786b1cc2b723a64dd592a7b'::TEXT, ARRAY[634]::BIGINT[]),
    (507::BIGINT, 'Explica bien, califica justo Deja tareas morales que es bueno hacerlas, si no, se molesta. Si va a consulta, que sea una duda específica, no le va a volver a explicar algo. Un poco engreído.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2016-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'afa7aa495d7782564e24f256d25fcc511c4b963e4df9cc75ffc0ce27d21e7edc'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-08-30T00:00:00+00:00'::TIMESTAMPTZ, '68fee3d594167e86c85691b8d87d4025b599d82b2fec09f4b4906df62f837a1f'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Él explica muy bien, pregunta frecuentemente si todos le están entendiendo. Es justo para calificar, pero eso sí cuídese de hacerlo justo como lo pide. Se pone odioso si le pregunta algo que ya dijo, pero por el resto es muy buen profesor. Ir bien con él queda en su responsabilidad y eso es bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '79d2c917320fbc179d2733861b38879344e0e5975d84893a471e931877c20b8a'::TEXT, ARRAY[563]::BIGINT[]),
    (507::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'a158b49941b6ba0bf386e858d5398b74f20407184b57739712fb0d46147defd9'::TEXT, ARRAY[935]::BIGINT[]),
    (507::BIGINT, 'Explica muy bien y es muy metódico sin embargo, a veces en temas muy específicos no sabe mucho pero en general es bueno, califica ni muy suave ni muy duro. Hace quices cada semana sin falta.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, '2b12a58577809d2489a1b346971cb4e7788d488287f49f249b3c681adf226cf2'::TEXT, ARRAY[1034]::BIGINT[]),
    (507::BIGINT, 'excelente Profesor, sumamente ordenado y metódico, realmente vale la pena matricular con él, la materia la explica de forma clara, su actitud y amabilidad en clase es muy agradable. si vas a consulta con él es mejor ir con preguntas concisas, ya que es de pocas palabras en la consulta'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'cff8d44bb3b03a84859fe6ba7a437b208416bdfe624b87a05fab366c1a1542b3'::TEXT, ARRAY[2439]::BIGINT[]),
    (507::BIGINT, 'Es un buen profe explicando, no tan amable siento que no le agrada mucho ir a consulta pero con lo que se ve en clase se pasan los exámenes colegiados'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'd283242192e337ae35c3a6fa42fdbb92bd44f606569d8977bfbee414a700d2c5'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
